-- Sincronizacion de las secuencias SERIAL
SELECT setval(pg_get_serial_sequence('marcas', 'id_marca'), COALESCE((SELECT MAX(id_marca) FROM marcas), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('categorias', 'id_categoria'), COALESCE((SELECT MAX(id_categoria) FROM categorias), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('talles', 'id_talle'), COALESCE((SELECT MAX(id_talle) FROM talles), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('colores', 'id_color'), COALESCE((SELECT MAX(id_color) FROM colores), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('sucursales', 'id_sucursal'), COALESCE((SELECT MAX(id_sucursal) FROM sucursales), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('proveedores', 'id_proveedor'), COALESCE((SELECT MAX(id_proveedor) FROM proveedores), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('empleados', 'id_empleado'), COALESCE((SELECT MAX(id_empleado) FROM empleados), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('productos', 'id_producto'), COALESCE((SELECT MAX(id_producto) FROM productos), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('producto_variante', 'id_variante'), COALESCE((SELECT MAX(id_variante) FROM producto_variante), 0) + 1, false);
